/* CD read poll (retail entry 0x800811E4), clean-room.
 *
 *   int pe_plat_cdhost_readpoll(uint32_t fp)      (bound by pe_plat/cdhost.h; former names pe_plat_cd_read_poll / pe_plat_cd_read_poll_host)
 *
 * PROVENANCE.  Written from the black-box vector sets cdgen50 `poll_stop.txt` (2200 cases; the retail routine with the abort entry stopped as one callee) and, for
 * the contrast, `poll.txt` (same states with the abort body expanded inline), generated by the vector lane (sw-vec-cdgen50; report and hashes in
 * docs/evidence/native-cdx-20261126/cdgen50, read through the L / S / RETS / CALL columns only), the checker pe_cdx_cdgen50_check.c, the public headers
 * (pe_plat/cd.h, pe_plat/cdhost.h, pe_plat/hostfb_forward.h, bootstrap/game_port.h) and the task statement of the coordinator (what DsRead stores and what the loader expects
 * of this entry).  NOT read: the previous provider of this entry (pe_plat_cd_poll.c, both the independent core and the host adapter in it), src/, asm/, vendor/,
 * decomp_hand/, game/boot bodies, pe_lib*.c, pe_stream.c, *_retail.c, oracle sources, retail_*_cases.h.  The behaviour below is what the vectors show.
 *
 * Guest words (little endian, read at every use):
 *   0x8009B6C4  retrace stamp stored by the read start (the VSync(-1) value when the read was issued)
 *   0x8009B6B4  remaining-sector / status word the poll reports (returned unchanged on the normal path)
 *
 * Behaviour, one pass per call (the loaders call it again until it reports completion or a time-out; the VSync(-1) call is the per-poll clock tick: the host retrace
 * clock advances the CD device model on every call):
 *   now   = VSync(-1)                                       callee 0x80073A44, argument -1, first call of every case
 *   limit = [0x8009B6C4] + 0x4B0 (1200 retraces, 32-bit wrap)
 *   (int)now > (int)limit     -> time-out: abort entry 0x80081268 (callee, no arguments), then ready entry 0x8007F608(fp), return -1
 *                                (2200 / 2200 vectors, signed compare: stamps 0x7FFFFB50 .. 0x80000000 and now = 0x7FFFFFFF / 0x80000000 / 0xFFFFFFFF separate every unsigned or
 *                                 unwrapped variant)
 *   otherwise                 -> ready entry 0x8007F608(fp) (the argument is passed through unchanged, 2200 / 2200), return [0x8009B6B4]
 *                                (1221 / 1221; the return value of the ready entry is never used: 235 / 1221 agree by chance)
 * The expired path never reads 0x8009B6B4; the normal path never stores.  In poll.txt the abort body is run inline by the oracle: it stores 0 to 0x8009B6CC and calls
 * 0x8007F69C, 0x800822BC, (0x800824F0), 0x8007FCBC, 0x8007EE84 depending on the driver state; the native abort entry `pe_plat_ds_81268` owns that work, so this
 * provider calls it as a callee (the poll_stop.txt contract) instead of repeating it.
 *
 * Host contract (hardware wait): there is no loop in this entry, so no wait can spin here; a stop already requested returns -1 at once (the caller's loop ends) without
 * touching the CD driver, and every pass ticks the device through the retail VSync callee. */
#include <stdint.h>

#include "pe_guest_ram.h"
#include "game_port.h"
#include "pe_plat/cd.h"
#include "pe_plat/cdhost.h"
#include "pe_plat/hostfb_forward.h"

#define RP_STAMP   0x8009B6C4u   /* retrace stamp of the read start */
#define RP_STATUS  0x8009B6B4u   /* remaining sectors / status */
#define RP_EXPIRY  0x4B0u        /* 1200 retraces */

int pe_plat_cdhost_readpoll(uint32_t fp)
{
    uint32_t now, limit;

    if (PE_Port_ShouldStop())
        return -1;
    now = (uint32_t)func_80073A44(-1);                    /* retail VSync(-1): the retrace clock, and the device tick */
    limit = PE_LoadU32(RP_STAMP) + RP_EXPIRY;
    if ((int32_t)now > (int32_t)limit) {
        func_80081268();                                  /* abort the read in flight */
        (void)func_8007F608((int)fp);
        return -1;
    }
    (void)func_8007F608((int)fp);
    return (int)PE_LoadU32(RP_STATUS);
}
